                Arguments.of("  Ada  ", "  Lovelace ", "Ada Lovelace"),
                Arguments.of("María\tJosé", "de\n la  Cruz", "María José de la Cruz"),
                Arguments.of("Élodie", "D'Alembert", "Élodie D'Alembert"));
